type Action =
    | { type: "ADD_ITEM"; payload: { name: string; price: number } }
    | { type: "REMOVE_ITEM"; payload: { name: string } }
    | { type: "CLEAR" }
    | { type: "APPLY_DISCOUNT"; payload: { percent: number } }

type State = { items: { name: string; price: number }[]; discount: number }

function reducer(state: State, action: Action): State {
    switch (action.type) {
        case "ADD_ITEM":
            return { ...state, items: [...state.items, action.payload] }
        case "REMOVE_ITEM":
            return { ...state, items: state.items.filter(i => i.name !== action.payload.name) }
        case "CLEAR":
            return { items: [], discount: 0 }
        case "APPLY_DISCOUNT":
            return { ...state, discount: action.payload.percent }
    }
}

