type Token = { t: "num"; v: number } | { t: "op"; v: "+" | "-" | "*" } | { t: "paren"; v: "(" | ")" }
function tokenize(src: string): Token[] {
    const out: Token[] = []
    for (const m of src.matchAll(/\d+|[+\-*()]/g)) {
        const s = m[0]
        if (/\d/.test(s)) out.push({ t: "num", v: Number(s) })
        else if (s === "(" || s === ")") out.push({ t: "paren", v: s })
        else out.push({ t: "op", v: s as "+" | "-" | "*" })
    }
    return out
}
