type State =
    | { s: "idle" }
    | { s: "running"; since: number }
    | { s: "done"; result: string }

type Ev =
    | { e: "start"; at: number }
    | { e: "finish"; result: string }
    | { e: "reset" }

function next(state: State, ev: Ev): State {
    switch (state.s) {
        case "idle": return ev.e === "start" ? { s: "running", since: ev.at } : state
        case "running": return ev.e === "finish" ? { s: "done", result: ev.result } : state
        case "done": return ev.e === "reset" ? { s: "idle" } : state
    }
}

let state: State = { s: "idle" }
for (const ev of [{ e: "start", at: 100 }, { e: "finish", result: "OK" }, { e: "reset" }] as Ev[]) {
    state = next(state, ev)
    console.log(ev.e, "->", state)
}

