    invariant(amount > 0, "summa musbat bo'lishi kerak")
    invariant(amount <= balance, "mablag' yetarli emas")
    return balance - amount
}
console.log(withdraw(100, 30))
try { withdraw(100, 300) } catch (e) { console.log((e as Error).message) }

import { readFileSync } from "node:fs"

function isNodeError(e: unknown): e is Error & { code: string } {
    return e instanceof Error && "code" in e && typeof e.code === "string"
}

try {
    readFileSync("mavjud-bo'lmagan-fayl.txt")
} catch (e) {
    if (isNodeError(e)) console.log("Xato kodi:", e.code)
    else throw e
}

const isString = (x: unknown): x is string => typeof x === "string"
const isNumber = (x: unknown): x is number => typeof x === "number"
const isArray = (x: unknown): x is unknown[] => Array.isArray(x)

function classify(x: unknown): string {
    switch (true) {
        case isString(x): return `satr (${x.length} belgi)`
        case isNumber(x): return `son (${x.toFixed(1)})`
        case isArray(x): return `massiv (${x.length} element)`
        default: return "boshqa"
    }
}

console.log(["salom", 3.14, [1, 2], null].map(classify))

type Guard<T> = (x: unknown) => x is T

const isString: Guard<string> = (x): x is string => typeof x === "string"
const isNumber: Guard<number> = (x): x is number => typeof x === "number"

const or = <A, B>(a: Guard<A>, b: Guard<B>): Guard<A | B> => (x): x is A | B => a(x) || b(x)
const arrayOf = <T>(item: Guard<T>): Guard<T[]> => (x): x is T[] => Array.isArray(x) && x.every(item)

const isStringOrNumber = or(isString, isNumber)
const isIdList = arrayOf(isStringOrNumber)

console.log(isIdList([1, "a", 2]), isIdList([1, null]), isIdList("1,2"))
